import os

def word_count(file_name):
    text_file = open(file_name, 'r')
    text_lst = text_file.read().split()
    text_file.close()

    word_dict = {}
    for word in text_lst:
        if word in word_dict:
            word_dict[word] += 1
        else:
            word_dict[word] = 1

    top_words = sorted(word_dict.items(), key=lambda t: t[1], reverse=True)
    return top_words[:5]

if __name__ == '__main__':
    root_dir = os.getcwd()
    print("The top 5 words with the most occurrences in the files under the root directory:")
    for file_name in os.listdir(root_dir):
        if os.path.isfile(os.path.join(root_dir, file_name)):
            word_count(os.path.join(root_dir, file_name))
        else:
            print("Skipping directory: " + file_name)
    print("")<s>

