def findHCA(node1, node2): 
    # Traverse the tree from root 
    # to find the path from node1 to root 
    path1 = [node1] 
    while node1.parent is not None: 
        path1.append(node1.parent) 
        node1 = node1.parent 

    # Traverse the tree from root to find the path from node2 to root 
    path2 = [node2] 
    while node2.parent is not None: 
        path2.append(node2.parent) 
        node2 = node2.parent 

    # Find the lowest common ancestor of two nodes 
    # by comparing the paths 
    lowestCommonAncestor = None
    for i in range(len(path1)): 
        if path1[i] != path2[i]: 
            if lowestCommonAncestor is None: 
                lowestCommonAncestor = path1[i] 
            else: 
                lowestCommonAncestor = min(lowestCommonAncestor, path1[i]) 

    return lowestCommonAncestor<s>

