def common_elements(arr1, arr2):
    # Initialize a dictionary to store the common elements
    common_elements = {}

    # Iterate through both arrays
    for i in range(len(arr1)):
        # Check if element is already in the dictionary
        if i in common_elements:
            # If element is already present, increment count
            common_elements[i] += 1
        # If element is not present in the dictionary, add it
        else:
            common_elements[i] = 1

    # Iterate through arr2 and check if element is present in the dictionary
    for j in range(len(arr2)):
        if j in common_elements:
            # If element is present in the dictionary, increment count
            common_elements[j] += 1
        # If element is not present in the dictionary, add it
        else:
            common_elements[j] = 1

    # Return the common elements
    return common_elements

